package com.rpb.reservation.workforce;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.domain.WorkforceException;
import static com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import static com.rpb.reservation.workforce.payroll.CdacBulk.*;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class CdacBulkPostgresTest extends WorkforcePayrollConfigurationPostgresTest {
 CdacBulkService bulk;WorkforceJson json;
 @BeforeEach void bulkSetup(){json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());bulk=proxy(new CdacBulkService(access,payrollAccess,configuration,repository,new PayrollRepository(jdbc,json),new CdacBulkRepository(jdbc,json),new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules()),json));}
 Selection selection(String mode,String reference){return new Selection(company,"2026-11",List.of(employee),new CdacProfile(mode,reference));}
 PayProfile seed(){var t=template();return approvedProfile(admin,store,UUID.randomUUID(),profile(0,t));}
 @Test void previewThenApplyCreatesNewPlanAndReplaysWithoutChangingOtherFields(){
  var old=seed();var c=selection("exempt","Written exemption");var p=bulk.preview(admin,store,c);assertThat(p.ready()).isEqualTo(1);assertThat(p.rows().getFirst().sourceEffectiveFrom()).isEqualTo(old.effectiveFrom());
  UUID cmd=UUID.randomUUID();var write=new Write(c,p.fingerprint(),"Reviewed CDAC change");var result=bulk.apply(admin,store,cmd,write);assertThat(result.profiles()).isEmpty();assertThat(result.requests()).hasSize(1);assertThat(result.requests().getFirst().status()).isEqualTo("submitted");assertThat(bulk.apply(admin,store,cmd,write)).isEqualTo(result);
  var request=new com.rpb.reservation.workforce.payroll.governance.PayChangeRepository(jdbc,json).find(tenant,result.requests().getFirst().requestId()).orElseThrow();var next=request.content().profile();assertThat(next.rule()).isEqualTo(old.rule());assertThat(next.cpf()).isEqualTo(old.cpf());assertThat(next.payment()).isEqualTo(old.payment());assertThat(next.templateId()).isEqualTo(old.templateId());assertThat(next.effectiveFrom()).isEqualTo(LocalDate.of(2026,11,1));assertThat(next.cdac().status()).isEqualTo("exempt");assertThat(configuration.findProfile(tenant,old.id()).orElseThrow()).isEqualTo(old);
  assertThatThrownBy(()->bulk.apply(admin,store,cmd,new Write(selection("manual","review"),p.fingerprint(),"Reviewed CDAC change"))).isInstanceOf(WorkforceException.class);
 }
 @Test void exemptionAndManualNeedEvidenceAndCannotBeEmptySelection(){seed();for(String mode:List.of("exempt","manual"))assertThatThrownBy(()->bulk.preview(admin,store,selection(mode," "))).isInstanceOf(WorkforceException.class);assertThatThrownBy(()->bulk.preview(admin,store,new Selection(company,"2026-11",List.of(),new CdacProfile("applicable","")))).isInstanceOf(WorkforceException.class);assertThat(bulk.preview(admin,store,selection("manual","reviewed" )).ready()).isEqualTo(1);}
 @Test void changedSourceInvalidatesPreviewAndPreservesAllPlans(){var old=seed();var c=selection("applicable","");var p=bulk.preview(admin,store,c);approvedProfile(admin,store,old.id(),new ProfileWrite(1L,company,employee,old.effectiveFrom(),old.templateId(),rule("20.00"),cpf()));assertThatThrownBy(()->bulk.apply(admin,store,UUID.randomUUID(),new Write(c,p.fingerprint(),"Reviewed CDAC change"))).isInstanceOfSatisfying(WorkforceException.class,e->assertThat(e.code()).isEqualTo("WORKFORCE_CDAC_BULK_CHANGED"));assertThat(configuration.profiles(tenant,company)).hasSize(1);}
 @Test void confirmedMonthsAndExistingTargetMonthAreBlocked(){var old=seed();jdbc.update("insert into workforce_pay_batches(id,tenant_id,company_id,company_name,period_month,status,version,calculation,created_by,confirmed_by,confirmed_at) values(?,?,?,'Company','2026-11-01','confirmed',1,?::jsonb,?,?,now())",UUID.randomUUID(),tenant,company,"{\"lines\":[{\"employeeId\":\""+employee+"\",\"profile\":{\"id\":\""+old.id()+"\"}}]}",adminId,adminId);var c=selection("applicable","");assertThat(bulk.preview(admin,store,c).rows().getFirst().reason()).isEqualTo("CONFIRMED_MONTH");assertThat(bulk.preview(admin,store,new Selection(company,"2026-10",List.of(employee),c.cdac())).ready()).isZero();}
 @Test void sourceManualItemsAreNotSilentlyRemovedAndFuturePlansRemain(){var t=template();var manual=new Rule("monthly","1800","8","44",false,"1.5",List.of(new Item("Old CDAC","cdac","1")));approvedProfile(admin,store,UUID.randomUUID(),new ProfileWrite(0L,company,employee,LocalDate.of(2026,10,1),t.id(),manual,cpf()));assertThat(bulk.preview(admin,store,selection("applicable","")).rows().getFirst().reason()).isEqualTo("CDAC_DUPLICATE");var future=approvedProfile(admin,store,UUID.randomUUID(),new ProfileWrite(0L,company,employee,LocalDate.of(2026,12,1),t.id(),manual,cpf()));var p=bulk.preview(admin,store,selection("manual","reviewed"));assertThat(p.rows().getFirst().nextEffectiveFrom()).isEqualTo(future.effectiveFrom());bulk.apply(admin,store,UUID.randomUUID(),new Write(selection("manual","reviewed"),p.fingerprint(),"Reviewed CDAC change"));assertThat(configuration.findProfile(tenant,future.id()).orElseThrow()).isEqualTo(future);}
 @Test void payrollPermissionStoreCoverageAndAppGateAreEnforcedBeforeReadingEmployees(){seed();var denied=manager(false,Set.of(store,sibling));assertThatThrownBy(()->bulk.preview(denied,store,selection("applicable",""))).isInstanceOf(WorkforceException.class);var limited=manager(true,Set.of(store));assertThatThrownBy(()->bulk.preview(limited,store,selection("applicable",""))).isInstanceOf(WorkforceException.class);var delegated=manager(true,Set.of(store,sibling));assertThat(bulk.preview(delegated,store,selection("applicable","")).ready()).isEqualTo(1);assertThatThrownBy(()->bulk.preview(admin,store,new Selection(otherCompany,"2026-11",List.of(employee),new CdacProfile("applicable","")))).isInstanceOf(WorkforceException.class);doThrow(WorkforceException.forbidden()).when(gate).evaluate(any());assertThatThrownBy(()->bulk.preview(admin,store,selection("applicable",""))).isInstanceOf(WorkforceException.class);}
 @Test void identicalSettingsAreUnchangedAndForeignEmployeesCannotBeAutomatic(){var t=template();approvedProfile(admin,store,UUID.randomUUID(),new ProfileWrite(0L,company,employee,LocalDate.of(2026,10,1),t.id(),t.rule(),new com.rpb.reservation.workforce.statutory.StatutoryDtos.CpfProfile("foreign",null,null,"GG",""),null,new CdacProfile("manual","reviewed")));assertThat(bulk.preview(admin,store,selection("manual","reviewed")).unchanged()).isEqualTo(1);assertThat(bulk.preview(admin,store,selection("applicable","")).rows().getFirst().reason()).isEqualTo("CDAC_PROFILE_INVALID");}
 @Test void noSourceAndTargetMonthPlanHaveExplicitReasons(){assertThat(bulk.preview(admin,store,selection("applicable","")).rows().getFirst().reason()).isEqualTo("PROFILE_MISSING");seed();assertThat(bulk.preview(admin,store,new Selection(company,"2026-10",List.of(employee),new CdacProfile("applicable",""))).rows().getFirst().reason()).isEqualTo("TARGET_MONTH_EXISTS");}
 @Test void auditingFailureRollsBackTheNewPlanAndReceipt(){seed();var c=selection("exempt","reviewed");var p=bulk.preview(admin,store,c);UUID cmd=UUID.randomUUID();doThrow(new IllegalStateException("audit failure")).when(logs).append(any(com.rpb.reservation.common.scope.StoreScope.class),any());assertThat(bulk.apply(admin,store,cmd,new Write(c,p.fingerprint(),"Reviewed CDAC change")).requests().getFirst().error()).isEqualTo("WORKFORCE_PAYROLL_CHANGE_FAILED");assertThat(configuration.profiles(tenant,company)).hasSize(1);assertThat(jdbc.queryForObject("select count(*) from workforce_cdac_bulk_commands where id=?",Integer.class,cmd)).isEqualTo(1);}
 @Test void permissionRevocationAppliesToCommandReplay(){seed();var delegated=manager(true,Set.of(store,sibling));var c=selection("applicable","");var p=bulk.preview(delegated,store,c);UUID cmd=UUID.randomUUID();var w=new Write(c,p.fingerprint(),"Reviewed CDAC change");bulk.apply(delegated,store,cmd,w);jdbc.update("delete from workforce_administrators where tenant_id=? and account_id=?",tenant,delegated.actorId());assertThatThrownBy(()->bulk.apply(delegated,store,cmd,w)).isInstanceOf(WorkforceException.class);}
 @Test void concurrentReplaysCreateExactlyOnePlan()throws Exception{seed();var c=selection("applicable","");var p=bulk.preview(admin,store,c);UUID cmd=UUID.randomUUID();var w=new Write(c,p.fingerprint(),"Reviewed CDAC change");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var first=pool.submit(()->bulk.apply(admin,store,cmd,w));var second=pool.submit(()->bulk.apply(admin,store,cmd,w));assertThat(first.get(20,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(second.get(20,java.util.concurrent.TimeUnit.SECONDS));}assertThat(configuration.profiles(tenant,company)).hasSize(1);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_change_requests where tenant_id=? and status='submitted'",Integer.class,tenant)).isEqualTo(1);}
}
